import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { Eye, EyeOff, Leaf, ArrowRight } from 'lucide-react';

function Login() {
  const [showPassword, setShowPassword] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const navigate = useNavigate();

  const handleSubmit = (event) => {
    event.preventDefault();
    setError('');

    if (!email.trim() || !password) {
      setError('Please enter your email and password.');
      return;
    }

    setError(
      'Login is not connected yet. Authentication will be added in the next step.'
    );
  };

  return (
    <main className="auth-page">
      <section className="auth-card">
        <Link to="/" className="auth-brand">
          <span className="auth-brand-icon">✦</span>
          Craft<span>Lanka</span>
        </Link>

        <div className="auth-heading">
          <p className="eyebrow">WELCOME BACK</p>
          <h1>Good to see <span>you.</span></h1>
          <p>Sign in to explore handmade treasures from Sri Lanka.</p>
        </div>

        <form onSubmit={handleSubmit} className="auth-form">
          <label>
            Email Address
            <input
              type="email"
              placeholder="you@example.com"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              autoComplete="email"
              required
            />
          </label>

          <label>
            Password
            <div className="auth-password">
              <input
                type={showPassword ? 'text' : 'password'}
                placeholder="Enter your password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                autoComplete="current-password"
                required
              />
              <button
                type="button"
                className="auth-eye"
                onClick={() => setShowPassword(!showPassword)}
                aria-label={showPassword ? 'Hide password' : 'Show password'}
              >
                {showPassword ? <EyeOff size={19} /> : <Eye size={19} />}
              </button>
            </div>
          </label>

          {error && <p className="auth-message" role="alert">{error}</p>}

          <button type="submit" className="auth-submit">
            Sign In <ArrowRight size={18} />
          </button>
        </form>

        <p className="auth-switch">
          Don't have an account? <Link to="/signup">Create Account</Link>
        </p>

        <div className="auth-back">
          <Leaf size={15} />
          <Link to="/">Back to CraftLanka</Link>
        </div>
      </section>

      <aside className="auth-visual">
        <div className="auth-visual-overlay">
          <p>MADE WITH LOVE, ROOTED IN CULTURE</p>
          <h2>Every craft tells a story.</h2>
          <span>Discover the hands and heritage behind Sri Lankan handmade treasures.</span>
        </div>
      </aside>
    </main>
  );
}

export default Login;
